  const createIcons = function (options) {
    const root = (options && options.root) || document;
    const elements = root.querySelectorAll('[data-lucide]');
    elements.forEach(function (element) {
      const name = element.getAttribute('data-lucide');
      if (!name) return;
      const camel = toCamelCase(name);
      const pascal = camel.charAt(0).toUpperCase() + camel.slice(1);
      const iconNode = icons[name] || icons[camel] || icons[pascal];
      if (!iconNode) return;

      const customAttrs = {};
      for (let i = 0; i < element.attributes.length; i++) {
        const attr = element.attributes[i];
        if (attr.name !== 'data-lucide') {
          customAttrs[attr.name] = attr.value;
        }
      }
      const svg = createElement(iconNode, customAttrs);
      element.parentNode.replaceChild(svg, element);
    });
  };

  global.lucide = {
    icons: icons,
    createIcons: createIcons,
    createElement: createElement
  };
